/** Offline KNUST outlines. The pack is generated by scripts/import-knust-footprints.py. */

import { campusFootprintPack } from '@/assets/campus-footprints';
import { containsPoint, nearestOnOutline, toLocal, type LngLat } from '@/lib/footprint';

type CatalogEntrance = LngLat & { name: string };
type CatalogBuilding = {
  id: number;
  name: string | null;
  ring: LngLat[];
  areaM2: number;
  perimeterM: number;
  axisDeg: number;
  entrances: CatalogEntrance[];
};

export type FootprintItem = [
  number,
  string | null,
  number,
  number,
  number,
  number[][],
  [string, number, number][],
  number,
  number,
];

export type FootprintPack = {
  v: number;
  bbox: number[];
  note: string;
  items: FootprintItem[];
};

const CELL = 0.002;

const grid = new Map<string, number[]>();

campusFootprintPack.items.forEach((item, index) => {
  let minLat = 90;
  let maxLat = -90;
  let minLng = 180;
  let maxLng = -180;
  for (const pair of item[5]) {
    minLng = Math.min(minLng, pair[0]);
    maxLng = Math.max(maxLng, pair[0]);
    minLat = Math.min(minLat, pair[1]);
    maxLat = Math.max(maxLat, pair[1]);
  }
  const lat0 = Math.floor(minLat / CELL);
  const lat1 = Math.floor(maxLat / CELL);
  const lng0 = Math.floor(minLng / CELL);
  const lng1 = Math.floor(maxLng / CELL);
  for (let lat = lat0; lat <= lat1; lat += 1) {
    for (let lng = lng0; lng <= lng1; lng += 1) {
      const key = `${lat}:${lng}`;
      const bucket = grid.get(key);
      if (bucket) bucket.push(index);
      else grid.set(key, [index]);
    }
  }
});

function asRing(pairs: number[][]): LngLat[] {
  return pairs.map((pair) => ({ longitude: pair[0], latitude: pair[1] }));
}

function asEntrances(rows: [string, number, number][]): CatalogEntrance[] {
  return rows.map((row) => ({ name: row[0] || 'Entrance', longitude: row[1], latitude: row[2] }));
}

/** Buildings whose outline contains the point, or passes within radiusM of it. */
export function footprintsNear(latitude: number, longitude: number, radiusM = 70): CatalogBuilding[] {
  if (!Number.isFinite(latitude) || !Number.isFinite(longitude)) return [];
  const pad = Math.max(1, Math.ceil(radiusM / 111320 / CELL));
  const latCell = Math.floor(latitude / CELL);
  const lngCell = Math.floor(longitude / CELL);
  const seen = new Set<number>();
  const hits: { building: CatalogBuilding; distance: number }[] = [];
  for (let lat = latCell - pad; lat <= latCell + pad; lat += 1) {
    for (let lng = lngCell - pad; lng <= lngCell + pad; lng += 1) {
      const bucket = grid.get(`${lat}:${lng}`);
      if (!bucket) continue;
      for (const index of bucket) {
        if (seen.has(index)) continue;
        seen.add(index);
        const item = campusFootprintPack.items[index];
        const ring = asRing(item[5]);
        if (ring.length < 3) continue;
        const origin = ring[0];
        const local = ring.map((point) => toLocal(origin, point));
        const here = toLocal(origin, { latitude, longitude });
        const inside = containsPoint(here, local, 0.4);
        const distance = inside ? 0 : nearestOnOutline(here, local).distance;
        if (!inside && distance > radiusM) continue;
        hits.push({
          distance,
          building: {
            id: item[0],
            name: item[1],
            ring,
            areaM2: item[2],
            perimeterM: item[3],
            axisDeg: item[4],
            entrances: asEntrances(item[6]),
          },
        });
      }
    }
  }
  hits.sort((a, b) => a.distance - b.distance || b.building.areaM2 - a.building.areaM2);
  return hits.map((hit) => hit.building);
}
